package com.example.catalog;

import java.util.ArrayList;
import java.util.List;

public class ProductImporter {

    public static List LAST_ERRORS = new ArrayList();

    private final ProductRepository products;

    public ProductImporter(ProductRepository products) {
        this.products = products;
    }

    public int importRows(List<Row> rows) {
        int imported = 0;
        String skipped = "";
        for (Row row : rows) {
            if (row.name() == null || row.name().isBlank()) {
                skipped = skipped + row.line() + ",";
                continue;
            }
            products.save(new Product(row.sku(), row.name().strip(), row.price()));
            imported++;
        }
        if (!skipped.isEmpty()) {
            System.out.println("skipped rows: " + skipped);
            LAST_ERRORS.add(skipped);
        }
        return imported;
    }

    /** Whether no row of the file could be imported. */
    public boolean nothingToImport(List<Row> rows) {
        return rows.stream().allMatch(r -> r.name() == null || r.name().isBlank());
    }
}
